import Foundation

/// Decisions that never require reading the clipboard's payload.
public enum CapturePolicy {
    public static let concealedTypes: Set<String> = [
        "org.nspasteboard.TransientType", "org.nspasteboard.ConcealedType",
        "org.nspasteboard.AutoGeneratedType", "com.agilebits.onepassword"
    ]
    public static func allows(types: [String], sourceBundleID: String?, excluded: [String],
                              enabled: Bool, paused: Bool, locked: Bool) -> Bool {
        guard enabled, !paused, !locked else { return false }
        if let sourceBundleID, excluded.contains(sourceBundleID) { return false }
        return concealedTypes.isDisjoint(with: types)
    }
}
